node -e '
const fs=require("fs");
const h=fs.readFileSync("game.html","utf8");
const js=h.match(/<script>\n([\s\S]*)\n<\/script>/)[1];
const i=js.indexOf("   9. UI");
const core=js.slice(0, js.lastIndexOf("/* =====",i));
new (require("vm").Script)(js); console.log("SYNTAX OK, full js chars:",js.length);
global.document={documentElement:{innerHTML:"nothing"}};
const extra=`
global.__out=runTests();
global.__b1=runBenchmark(newGame(1337),200);
global.__b2=runBenchmark(newGame(1337),200);
`;
require("vm").runInThisContext(core+extra);
let bad=0; global.__out.forEach((t,n)=>{ if(!t.p){bad++;console.log("FAIL",n+1,t.n,"|",t.x);} });
console.log("TESTS:",global.__out.length-bad,"/",global.__out.length,"passed");
console.log("BENCH:",JSON.stringify(global.__b1));
console.log("DETERMINISTIC:",global.__b1.hash===global.__b2.hash);
'
